-- UK per-flight hulls (generated by gen_uk_network.mjs). Expects
-- tmp_uk_flights(flight_id, flight_number) staged by seed_uk.sh. Additive:
-- only flights without inventory get a record. Run against skybook_inventory.

CREATE TEMP TABLE uk_hulls (flight_number varchar(10), hull varchar(6));

WITH regs AS (
  SELECT h.flight_number,
         CASE h.hull
           WHEN 'BAJ' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-SBBA')
           WHEN 'BAC' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-SBBC')
           WHEN 'U2A' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-EZSB')
           WHEN 'U2B' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-EZSA')
           WHEN 'EIA' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-EAGS')
           WHEN 'LMA' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-LMSA')
           WHEN 'LM4' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-LMSB')
           WHEN 'LME' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-LMSC')
           WHEN 'LMT' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-LMST')
           WHEN 'LMI' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-LMSI')
           WHEN 'RKA' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-RUKS')
           WHEN 'GRA' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-GRSA')
           WHEN 'GRD' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-GRSD')
           WHEN 'YT8' THEN (SELECT id FROM aircraft WHERE registration_number = 'G-SBYT')
         END AS aircraft_id
  FROM uk_hulls h
)
   total_seats, available_seats, held_seats, reserved_seats, blocked_seats)
SELECT now(), now(), 'data-seed-uk', 0, t.flight_id, r.aircraft_id, 'OPEN',
  a.total_seats, a.total_seats, 0, 0, 0
FROM tmp_uk_flights t
JOIN regs r ON r.flight_number = t.flight_number
JOIN aircraft a ON a.id = r.aircraft_id
WHERE NOT EXISTS (SELECT 1 FROM flight_inventory fi WHERE fi.flight_id = t.flight_id);

SELECT a.registration_number, a.model, count(*) AS flights
FROM flight_inventory fi JOIN aircraft a ON a.id = fi.aircraft_id
WHERE fi.created_by = 'data-seed-uk'
GROUP BY 1, 2 ORDER BY 3 DESC;
